require(['jquery'], function ($) {

  $.fn.multiPicker = function () {

    return this.each(function () {
      const select = $(this);

      if (select.data('mpInit')) {
        return;
      }
      select.data('mpInit', true);

      const originalName = select.attr('name');
      const hidden = select.siblings('input[type="hidden"][name="' + originalName + '"]').first();

      // The select itself no longer submits; the hidden field does
      select.addClass('mp-hidden-source').removeAttr('name');

      // Elements to build the multi picker ui
      const picker   = $('<div class="mp-picker"></div>');
      const search   = $('<input type="text" class="mp-search" autocomplete="off">');
      const dropdown = $('<div class="mp-dropdown"></div>');
      const list     = $('<ul class="mp-list" role="listbox"></ul>');

      // Counter for the elements of the list
      let itemIdCounter = 0;
      // Index of the currently keyboard highlighted item in the dropdown list.
      // -1 means nothing is highlighted.
      let activeIndex = -1;

      dropdown.append(list);
      picker.append(search, dropdown);
      select.after(picker);

      /**
       * Get the options from the select as an array of objects with value, text, and selected properties.
       */
      function getOptions() {
        return select.find('option').map(function () {
          return { value: String(this.value), text: $(this).text(), selected: this.selected };
        }).get();
      }

      function syncHidden() {
        if (!hidden.length) {
          return;
        }
        let values = getOptions()
          .filter(function (o) { return o.selected; })
          .map(function (o) { return o.value; });
        hidden.val(values.join(','));
      }

      function setSelected(value, isSelected) {
        select.find('option').each(function () {
          if (String(this.value) === value) {
            this.selected = isSelected;
          }
        });
        select.trigger('change');
        syncHidden();
      }

      function renderTags() {
        picker.find('.mp-tag').remove();
        getOptions().forEach(function (o) {
          if (!o.selected) {
            return;
          }
          let tag = $('<span class="mp-tag" tabindex="0"></span>').data('value', o.value);
          tag.append($('<span class="mp-tag-label"></span>').text(o.text));
          tag.append('<span class="mp-tag-remove">&times;</span>');
          search.before(tag);
        });
      }

      function getItems() {
        return list.find('.mp-item');
      }

      function setActive(index) {
        const items = getItems();
        items.removeClass('mp-active').attr('aria-selected', 'false');
        if (index < 0 || index >= items.length) {
          activeIndex = -1;
          search.removeAttr('aria-activedescendant');
          return;
        }

        activeIndex = index;
        const item = items.eq(index);
        item.addClass('mp-active').attr('aria-selected', 'true');
        search.attr('aria-activedescendant', item.attr('id'));
        // keep the highlighted item in view
        const itemEl = item.get(0);

        if (itemEl && itemEl.scrollIntoView) {
          itemEl.scrollIntoView({ block: 'nearest' });
        }
      }

      function nextActiveItemIndex(activeIndex, delta) {
        let next = activeIndex + delta;
        // Wrap around the item list
        if (next < 0) {
          next = items.length - 1;
        } else if (next >= items.length) {
          next = 0;
        }
        return next
      }

      function moveActive(delta) {
        const items = getItems();
        if (!items.length) {
          return;
        }
        let next = nextActiveItemIndex(activeIndex, delta);
        setActive(next);
      }

      function selectItem(item) {
        if (!item || !item.length) {
          return;
        }
        const value = item.data('value');
        setSelected(value, true);
        renderTags();
        renderList('');
        search.val('').trigger('focus');
      }

      function renderList(filter) {
        list.empty();
        activeIndex = -1;
        search.removeAttr('aria-activedescendant');
        let f = (filter || '').toLowerCase();
        let opts = getOptions();
        let shown = 0;

        opts.forEach(function (o) {
          if (o.selected) {
            return;
          }
          if (f && o.text.toLowerCase().indexOf(f) === -1) {
            return;
          }
          shown++;
          $('<li class="mp-item" role="option" tabindex="-1" id="mp-item-' + (itemIdCounter++) + '" aria-selected="false"></li>')
            .text(o.text)
            .data('value', o.value)
            .appendTo(list);
        });

        if (shown === 0) {
          $('<li class="mp-empty"></li>').text('No matches').appendTo(list);
        }
      }

      function openDropdown() {
        picker.addClass('mp-focused');
        dropdown.addClass('open');
        search.attr('aria-expanded', 'true');
        renderList(search.val());
      }

      function closeDropdown() {
        picker.removeClass('mp-focused');
        dropdown.removeClass('open');
        search.attr('aria-expanded', 'false');
        setActive(-1);
      }

      function clearActiveTags() {
        picker.find('.mp-tag-active').removeClass('mp-tag-active');
      }

      function removeTag(tag) {
        let value = tag.data('value');
        setSelected(String(value), false);
        renderTags();
        renderList(search.val());
      }

      // Accessibility wiring for the search input as a combobox
      search.attr({
        role: 'combobox',
        'aria-autocomplete': 'list',
        'aria-expanded': 'false',
        'aria-haspopup': 'listbox'
      });

      // clicking anywhere in the box (but not on a tag) opens the dropdown
      picker.on('click', function (e) {
        if ($(e.target).closest('.mp-tag').length) {
          return;
        }
        clearActiveTags();
        search.trigger('focus');
        openDropdown();
      });

      search.on('focus click', openDropdown);

      search.on('input', function () {
        renderList($(this).val());
        dropdown.addClass('open');
      });

      // Escape closes the dropdown. Backspace on an empty field removes the last tag.
      // Arrow keys move the keyboard highlight through the list, Enter selects it.
      search.on('keydown', function (e) {
        if (e.key === 'Escape') {
          closeDropdown();
          search.trigger('blur');
          return;
        }
        if (e.key === 'Backspace' && search.val() === '') {
          var $lastTag = picker.find('.mp-tag').last();
          if ($lastTag.length) {
            removeTag($lastTag);
          }
          return;
        }
        if (e.key === 'ArrowDown') {
          e.preventDefault();
          if (!dropdown.hasClass('open')) {
            openDropdown();
          }
          moveActive(1);
          return;
        }
        if (e.key === 'ArrowUp') {
          e.preventDefault();
          if (!dropdown.hasClass('open')) {
            openDropdown();
          }
          moveActive(-1);
          return;
        }
        if (e.key === 'Enter') {
          if (dropdown.hasClass('open') && activeIndex > -1) {
            e.preventDefault();
            selectItem(getItems().eq(activeIndex));
          }
          return;
        }
        if (e.key === 'Tab' && !e.shiftKey) {
          // Move focus forward into the dropdown list (if open and populated)
          // instead of jumping straight past it.
          const items = getItems();
          if (dropdown.hasClass('open') && items.length) {
            e.preventDefault();
            setActive(0);
            items.eq(0).trigger('focus');
          }
        }
      });

      // Clicking the (x) removes the tag immediately
      picker.on('click', '.mp-tag-remove', function (e) {
        e.stopPropagation();
        removeTag($(this).closest('.mp-tag'));
        search.trigger('focus');
      });

      // Click the tag body (not the x) to mark it active & Backspace/Delete then removes it
      picker.on('click', '.mp-tag', function (e) {
        if ($(e.target).hasClass('mp-tag-remove')) {
          return;
        }
        e.stopPropagation();
        let tag = $(this);
        let alreadyActive = tag.hasClass('mp-tag-active');
        clearActiveTags();
        if (!alreadyActive) {
          tag.addClass('mp-tag-active');
          tag.trigger('focus');
        }
      });

      picker.on('keydown', '.mp-tag', function (e) {
        if (e.key === 'Backspace' || e.key === 'Delete') {
          e.preventDefault();
          removeTag($(this));
          search.trigger('focus');
        }
      });

      picker.on('blur', '.mp-tag', function () {
        $(this).removeClass('mp-tag-active');
      });

      // Add a value on click
      list.on('click', '.mp-item', function () {
        selectItem($(this));
      });

      list.on('mouseenter', '.mp-item', function () {
        setActive(getItems().index(this));
      });

      // Keyboard interaction once focus has moved onto an item (via Tab)
      list.on('keydown', '.mp-item', function (e) {
        const items = getItems();
        const idx = items.index(this);

        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          selectItem($(this));
          return;
        }
        if (e.key === 'ArrowDown') {
          e.preventDefault();
          const next = items.eq((idx + 1) % items.length);
          setActive(items.index(next));
          next.trigger('focus');
          return;
        }
        if (e.key === 'ArrowUp') {
          e.preventDefault();
          const prev = items.eq((idx - 1 + items.length) % items.length);
          setActive(items.index(prev));
          prev.trigger('focus');
          return;
        }
        if (e.key === 'Escape') {
          closeDropdown();
          search.trigger('focus');
          return;
        }
        if (e.key === 'Tab' && e.shiftKey) {
          // Shift+Tab from the first item goes back to the search field
          if (idx === 0) {
            e.preventDefault();
            search.trigger('focus');
          }
        }
        // Tab (forward) from the last item is left to the browser default,
        // which moves focus out of the picker to the next control on the page.
      });

      list.on('focus', '.mp-item', function () {
        setActive(getItems().index(this));
      });

      // Close dropdown / clear active tag when clicking outside
      $(document).on('click', function (e) {
        if (!picker.is(e.target) && picker.has(e.target).length === 0) {
          closeDropdown();
          clearActiveTags();
        }
      });

      // Close the dropdown when focus moves outside the whole widget via keyboard
      picker.on('focusout', function () {
        setTimeout(function () {
          const active = document.activeElement;
          if (!picker.is(active) && picker.has(active).length === 0) {
            closeDropdown();
          }
        }, 0);
      });

      renderTags();
      renderList('');
      syncHidden();
    });
  };

  function init() {
    $('select.chosen-bannedField-select').multiPicker();
  }
  $(init);
  $(document).on('xwiki:dom:updated', init);

});

.mp-picker {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  min-height: 42px;
  padding: 6px 8px;
  background: #fff;
  border: 1px solid #dfe1e6;
  border-radius: 6px;
  cursor: text;
  transition: border-color .15s ease, box-shadow .15s ease;
}

.mp-picker.mp-focused {
  border-color: #4c9aff;
  box-shadow: 0 0 0 1px #4c9aff;
}

.mp-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #efefef;
  color: #172b4d;
  border-radius: 4px;
  padding: 4px 6px 4px 10px;
  font-size: 13px;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
  transition: background .12s ease, color .12s ease;
}

.mp-tag:hover {
  background: #326194;
  color: #fff;
}

.mp-tag.mp-tag-active {
  background: #326194;
  color: #fff;
}

.mp-tag:focus {
  outline: 2px solid #4c9aff;
  outline-offset: 2px;
}

.mp-tag-remove {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  font-size: 14px;
  line-height: 1;
  color: inherit;
  cursor: pointer;
}

.mp-tag:hover .mp-tag-remove {
  background: rgba(255, 255, 255, .2);
}

.mp-picker input.mp-search {
  flex: 1 0 80px;
  min-width: 80px;
  height: auto !important;
  margin: 0 !important;
  padding: 4px 2px !important;
  border: none !important;
  border-radius: 0 !important;
  outline: none !important;
  box-shadow: none !important;
  background: transparent !important;
  font-size: 14px;
  color: #172b4d;
}

.mp-picker input.mp-search:focus {
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
}

.mp-dropdown {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  margin-top: 4px;
  background: #fff;
  border: 1px solid #dfe1e6;
  border-radius: 6px;
  box-shadow: 0 4px 11px rgba(9, 30, 66, .15);
  max-height: 260px;
  overflow-y: auto;
  z-index: 20;
  display: none;
}

.mp-dropdown.open {
  display: block;
}

.mp-list {
  list-style: none;
  margin: 0;
  padding: 4px 0;
}

.mp-item {
  padding: 8px 14px;
  font-size: 14px;
  color: #172b4d;
  cursor: pointer;
}

.mp-item:hover,
.mp-item.mp-active,
.mp-item:focus {
  background: #326194;
  color: #fff;
}

.mp-empty {
  padding: 10px 14px;
  font-size: 13px;
  color: #6b778c;
  font-style: italic;
}

select.mp-hidden-source {
  display: none;
}
